create table restaurants(id uuid primary key,name text not null,slug text not null unique,currency text not null default 'EUR',stripe_account_id text,created_at timestamptz not null default now());
create table restaurant_tables(id uuid primary key,restaurant_id uuid not null references restaurants(id),label text not null,external_id text not null,active boolean not null default true,unique(restaurant_id,external_id));
create table table_tokens(id uuid primary key,table_id uuid not null references restaurant_tables(id),token_hash text not null unique,active boolean not null default true,created_at timestamptz not null default now());
create table menu_categories(id uuid primary key,restaurant_id uuid not null references restaurants(id),name text not null,sort_order integer not null default 0,active boolean not null default true);
create table menu_items(id uuid primary key,restaurant_id uuid not null references restaurants(id),category_id uuid not null references menu_categories(id),name text not null,description text,price_cents integer not null check(price_cents>=0),allergens text[] not null default '{}',image_url text,available boolean not null default true,sort_order integer not null default 0,updated_at timestamptz not null default now());
create table orders(id uuid primary key,restaurant_id uuid not null references restaurants(id),table_id uuid not null references restaurant_tables(id),external_order_id text not null,status text not null,total_cents integer not null check(total_cents>=0),paid_cents integer not null default 0 check(paid_cents>=0 and paid_cents<=total_cents),version integer not null default 1,created_at timestamptz not null default now(),unique(restaurant_id,external_order_id));
create table order_items(id uuid primary key,order_id uuid not null references orders(id) on delete cascade,external_item_id text,name text not null,quantity integer not null check(quantity>0),unit_cents integer not null check(unit_cents>=0));
create table payments(id uuid primary key,order_id uuid not null references orders(id),amount_cents integer not null check(amount_cents>0),currency text not null default 'EUR',status text not null,provider text not null,provider_payment_id text,idempotency_key text not null unique,created_at timestamptz not null default now());
create table payment_events(id bigserial primary key,payment_id uuid references payments(id),provider_event_id text unique,event_type text not null,payload jsonb not null,created_at timestamptz not null default now());
create table pos_sync_events(id bigserial primary key,restaurant_id uuid not null references restaurants(id),external_order_id text,event_type text not null,status text not null default 'PENDING',attempts integer not null default 0,payload jsonb not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index orders_table_status_idx on orders(table_id,status);
create index payments_order_idx on payments(order_id);
create index menu_items_restaurant_idx on menu_items(restaurant_id,available);
create index pos_sync_status_idx on pos_sync_events(status,created_at);
